-- =========================================================
-- Global Concepts Media Operating System
-- File: migrations/0027_schedule_operations.sql
-- Version: 1.0.0
-- Status: Production Migration Candidate
-- Purpose: Durable campaign/event schedule authority with human-reviewed
--          change candidates, version history, and one-source multi-calendar reads.
-- =========================================================
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schedule_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  client_id INTEGER,
  source_key TEXT NOT NULL UNIQUE,
  item_type TEXT NOT NULL,
  title TEXT NOT NULL,
  market TEXT,
  channel TEXT,
  start_date TEXT NOT NULL,
  end_date TEXT NOT NULL,
  start_time TEXT,
  status TEXT NOT NULL DEFAULT 'planned',
  source_reference TEXT,
  notes TEXT,
  metadata_json TEXT,
  version_number INTEGER NOT NULL DEFAULT 1,
  created_by TEXT NOT NULL DEFAULT 'Andy',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived_at TEXT,
  FOREIGN KEY (client_id) REFERENCES clients(id)
);
CREATE INDEX IF NOT EXISTS idx_schedule_items_dates ON schedule_items(start_date,end_date,status);
CREATE INDEX IF NOT EXISTS idx_schedule_items_client ON schedule_items(client_id,item_type,start_date);

CREATE TABLE IF NOT EXISTS schedule_change_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  client_id INTEGER,
  request_type TEXT NOT NULL,
  target_item_id INTEGER,
  title TEXT NOT NULL,
  proposed_json TEXT NOT NULL,
  reason TEXT,
  source_reference TEXT,
  status TEXT NOT NULL DEFAULT 'pending',
  requested_by TEXT NOT NULL DEFAULT 'Andy',
  reviewed_by TEXT,
  reviewed_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (client_id) REFERENCES clients(id),
  FOREIGN KEY (target_item_id) REFERENCES schedule_items(id)
);
CREATE INDEX IF NOT EXISTS idx_schedule_change_requests_status ON schedule_change_requests(status,created_at DESC);

CREATE TABLE IF NOT EXISTS schedule_item_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  schedule_item_id INTEGER NOT NULL,
  change_request_id INTEGER,
  version_number INTEGER NOT NULL,
  snapshot_json TEXT NOT NULL,
  change_type TEXT NOT NULL,
  changed_by TEXT NOT NULL DEFAULT 'Andy',
  changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (schedule_item_id) REFERENCES schedule_items(id),
  FOREIGN KEY (change_request_id) REFERENCES schedule_change_requests(id)
);
CREATE INDEX IF NOT EXISTS idx_schedule_item_history_item ON schedule_item_history(schedule_item_id,version_number DESC);

