INSERT OR IGNORE INTO schedule_item_history (schedule_item_id,version_number,snapshot_json,change_type,changed_by)
SELECT id,version_number,json_object(
 'sourceKey',source_key,'itemType',item_type,'title',title,'market',market,'channel',channel,
 'startDate',start_date,'endDate',end_date,'startTime',start_time,'status',status,
 'sourceReference',source_reference,'notes',notes,'metadataJson',metadata_json
),'seed','System' FROM schedule_items WHERE source_key LIKE 'ses:%';
